    .long 0x00000010, 0x84010204, op1f_duck_key_up, 0x6424bb53, 0    /* Ours deals with the keys of the sidechain's page; the firmware's own handling runs for every other key. */
    .long 0x00000010, 0x84010208, op1f_duck_encoder, 0xc9f1010d, 0    /* Ours: the knobs set the sidechain's source, amount, hold and release, and four more values with shift. */
